func (q *queue) stage(k Key, r Row) {
    q.mu.Lock(); q.dirty[k] = r; q.mu.Unlock()   // one entry per key
    select { case q.wake <- struct{}{}: default: } // never block the caller
}
func (q *queue) flush(ctx context.Context) error {
    q.mu.Lock(); batch := q.dirty; q.dirty = map[Key]Row{}; q.mu.Unlock()
    tx, err := db.BeginTx(ctx, nil)
    if err != nil { return err }
    defer tx.Rollback()
    for k, r := range batch {
        if _, err := tx.ExecContext(ctx, upsertSQL, r.V, k); err != nil { return err }
    }
    return tx.Commit()
}
